-- Initial catalogues. Run on the business database, under migration lock.
START TRANSACTION;
INSERT INTO T_EQUIPMENTTYPE (EQT_CH_NAME,EQT_DT_CREATION,EQT_CH_CREATION,EQT_N_ORDER)
SELECT s.n,UTC_TIMESTAMP(6),'migration',s.o FROM (
SELECT 'Serveur' n,10 o UNION ALL SELECT 'Machine virtuelle',20 UNION ALL SELECT 'NAS',30 UNION ALL SELECT 'Imprimante',40 UNION ALL SELECT 'Tablette',50 UNION ALL SELECT 'Téléphone',60 UNION ALL SELECT 'Ordinateur',70 UNION ALL SELECT 'Switch',80 UNION ALL SELECT 'Routeur',90 UNION ALL SELECT 'Prise',100 UNION ALL SELECT 'Onduleur',110 UNION ALL SELECT 'Périphérique',120 UNION ALL SELECT 'Fabrication',130 UNION ALL SELECT 'Conteneur',140
) s WHERE NOT EXISTS (SELECT 1 FROM T_EQUIPMENTTYPE WHERE EQT_CH_NAME=s.n AND EQT_N_MID IS NULL);
INSERT INTO T_RELATIONTYPE (RET_CH_NAME,RET_CH_INVERSE,RET_DT_CREATION,RET_CH_CREATION,RET_N_ORDER)
SELECT s.n,s.i,UTC_TIMESTAMP(6),'migration',s.o FROM (
SELECT 'Héberge' n,'Hébergé par' i,10 o UNION ALL SELECT 'Connecté en USB','Connecté en USB à',20 UNION ALL SELECT 'Alimente','Alimenté par',30 UNION ALL SELECT 'Connecté au réseau','Connecté au réseau à',40 UNION ALL SELECT 'Utilise le stockage','Fournit le stockage à',50
) s WHERE NOT EXISTS (SELECT 1 FROM T_RELATIONTYPE WHERE RET_CH_NAME=s.n AND RET_N_MID IS NULL);
INSERT INTO T_LINKTYPE (LKT_CH_NAME,LKT_DT_CREATION,LKT_CH_CREATION,LKT_N_ORDER)
SELECT s.n,UTC_TIMESTAMP(6),'migration',s.o FROM (
SELECT 'Administration' n,10 o UNION ALL SELECT 'Application',20 UNION ALL SELECT 'Supervision',30 UNION ALL SELECT 'API',40 UNION ALL SELECT 'Documentation',50 UNION ALL SELECT 'Dépôt source',60 UNION ALL SELECT 'Connexion distante',70 UNION ALL SELECT 'Stockage',80
) s WHERE NOT EXISTS (SELECT 1 FROM T_LINKTYPE WHERE LKT_CH_NAME=s.n AND LKT_N_MID IS NULL);
INSERT INTO T_RETENTIONPOLICY (RTP_N_RESOLUTION,RTP_N_DURATION,RTP_DT_CREATION,RTP_CH_CREATION,RTP_N_ORDER)
SELECT s.r,s.d,UTC_TIMESTAMP(6),'migration',s.o FROM (
SELECT 10 r,86400 d,10 o UNION ALL SELECT 60,2592000,20 UNION ALL SELECT 900,31536000,30 UNION ALL SELECT 3600,NULL,40
) s WHERE NOT EXISTS (SELECT 1 FROM T_RETENTIONPOLICY WHERE RTP_N_EQU_ID IS NULL AND RTP_N_MTT_ID IS NULL AND RTP_N_RESOLUTION=s.r AND RTP_N_MID IS NULL);
COMMIT;
